contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Param: callWithdrawAll - whether to invoke withdrawAll()
    function run(bool callWithdrawAll) public payable {
        // Read observable state before any actions
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeBalance = address(c).balance;

        bool withdrawReverted;
        // perform the state-changing call as a plain top-level statement
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            withdrawReverted = true;
        } else {
            withdrawReverted = false;
        }

        // Read observable state after the call
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint afterBalance = address(c).balance;

        // General rule: if withdrawAll was invoked and did NOT revert, then c.balance == 0
        // and depositsCount did not decrease (afterDeposits >= beforeDeposits).
        // We express implication using ||: if we did not call withdrawAll, treat as vacuously true by
        // allowing both possibilities of withdrawReverted; but the checker will explore the case
        // where withdrawAll is invoked. To ensure the assertion depends on the parameter,
        // include callWithdrawAll in the condition.
        assert(!callWithdrawAll || (callWithdrawAll && (withdrawReverted || (afterBalance == 0 && afterDeposits >= beforeDeposits))));
    }

    // allow receiving Ether for this test contract
    receive() external payable {}
}

