// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(bool callWithdrawAll) internal {
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        uint beforeBalance = address(c).balance;
        bool withdrawReverted;
        try c.withdrawAll() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint afterBalance = address(c).balance;
        assertTrue(!callWithdrawAll || (callWithdrawAll && (withdrawReverted || (afterBalance == 0 && afterDeposits >= beforeDeposits))));
    }

    function testFuzz_run(bool callWithdrawAll) public {
        _run(callWithdrawAll);
    }

    receive() external payable {}
}
